import { batch, createMemo, createSignal, onCleanup, onMount, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { makeEventListener } from "@solid-primitives/event-listener"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Tooltip } from "@opencode/ui/tooltip"
import { createKeyed, usePlugin } from "@opencode/plugin/gui"
import { motionGlobals, motionTuning } from "@opencode/ui/motion-tuning"
import { duration } from "@opencode/util/duration"
import { SessionTurn } from "@opencode/util/session-turn"
import { builtinContext } from "@opencode/plugin/gui/builtin"

type Mem = Performance & {
  memory?: {
    usedJSHeapSize: number
    jsHeapSizeLimit: number
  }
}

type Evt = PerformanceEntry & {
  interactionId?: number
  processingStart?: number
}

type Shift = PerformanceEntry & {
  hadRecentInput: boolean
  value: number
}

type Obs = PerformanceObserverInit & {
  durationThreshold?: number
}

type Readings = {
  cls: number | undefined
  delay: number | undefined
  fps: number | undefined
  gap: number | undefined
  focus: boolean
  heap: { limit: number | undefined; used: number | undefined }
  inp: number | undefined
  jank: number | undefined
  long: { block: number | undefined; count: number | undefined; max: number | undefined }
  nav: { dur: number | undefined; pending: boolean }
}

const span = 5000

const ms = (n?: number, d = 0) => {
  if (n === undefined || Number.isNaN(n)) return

  return `${n.toFixed(d)}ms`
}

const time = (n?: number) => {
  if (n === undefined || Number.isNaN(n)) return

  return `${Math.round(n)}`
}

const fixed = (n?: number, digits = 0) => {
  if (n === undefined || Number.isNaN(n)) return

  return n.toFixed(digits)
}

const mb = (n?: number) => {
  if (n === undefined || Number.isNaN(n)) return
  const v = n / 1024 / 1024

  return `${v >= 1024 ? v.toFixed(0) : v.toFixed(1)}MB`
}

const bad = (n: number | undefined, limit: number, low = false) => {
  if (n === undefined || Number.isNaN(n)) return false

  return low ? n < limit : n > limit
}

const session = (path: string) => path.includes("/session")

function Cell(props: {
  bad?: boolean
  dim?: boolean
  inline?: boolean
  label: string
  tip: string
  value: string
  span?: 2 | 3
}) {
  const content = () => (
    <div
      classList={{
        "flex min-w-0 items-center": true,
        "min-h-[20px] w-fit justify-start px-1.5 py-0.5 text-left": !!props.inline,
        "justify-center text-center": !props.inline,
        "min-h-[42px] w-full flex-col rounded-[8px] px-0.5 py-1": !props.inline,
        "col-span-2": props.span === 2 && !props.inline,
        "col-span-3": props.span === 3 && !props.inline,
      }}
    >
      <div
        classList={{
          "flex min-w-0": true,
          "-translate-y-px items-baseline gap-1.5": !!props.inline,
          "flex-col items-center": !props.inline,
        }}
      >
        <div
          dir="ltr"
          classList={{
            "text-[10px] leading-none font-black uppercase tracking-[0.04em] opacity-70": true,
          }}
        >
          {props.label}
        </div>
        <div
          dir="ltr"
          classList={{
            "uppercase font-bold tabular-nums": true,
            "text-[11px] leading-text-tight": !!props.inline,
            "text-[13px] leading-text-compact sm:text-[14px]": !props.inline,
            "text-text-on-critical-base": !!props.bad,
            "opacity-70": !!props.dim,
          }}
        >
          {props.value}
        </div>
      </div>
    </div>
  )

  return (
    <Tooltip appearance={props.inline ? "compact" : "standard"} value={props.tip} placement="top">
      {content()}
    </Tooltip>
  )
}

function ToggleCell(props: {
  active: boolean
  inline?: boolean
  label: string
  onClick: () => void
  tip: string
  value: string
}) {
  const content = () => (
    <button
      type="button"
      aria-label={`${props.label}: ${props.value}`}
      aria-pressed={props.active}
      classList={{
        "flex min-w-0 items-center font-mono uppercase hover:bg-surface-raised-base focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-v2-border-border-focus": true,
        "min-h-[20px] w-fit justify-start rounded px-1.5 py-0.5 text-left": !!props.inline,
        "min-h-[42px] w-full flex-col justify-center rounded-[8px] px-0.5 py-1 text-center": !props.inline,
        "bg-surface-raised-base text-text-strong": props.active,
      }}
      onClick={props.onClick}
    >
      <span
        classList={{
          flex: true,
          "-translate-y-px items-baseline gap-1.5": !!props.inline,
          "flex-col items-center": !props.inline,
        }}
      >
        <span dir="ltr" class="text-[10px] leading-none font-black tracking-[0.04em] opacity-70">
          {props.label}
        </span>
        <span dir="ltr" class="text-[11px] leading-none font-bold">
          {props.value}
        </span>
      </span>
    </button>
  )

  return (
    <Tooltip appearance={props.inline ? "compact" : "standard"} value={props.tip} placement="top">
      {content()}
    </Tooltip>
  )
}

export default function DebugBar(props: {
  diagnostics?: boolean
  inline?: boolean
  memory?: { on: boolean; env: boolean; toggle: () => void }
  motion?: { open: boolean; toggle: () => void }
  onClose?: () => void
}) {
  const ctx = builtinContext(usePlugin())
  const router = ctx.router
  const locale = ctx.locale
  const desktop = ctx.desktop
  const sessions = ctx.sessions

  const [state, setState] = createStore<Readings>({
    cls: undefined,
    delay: undefined,
    fps: undefined,
    gap: undefined,
    focus: false,
    heap: {
      limit: undefined,
      used: undefined,
    },
    inp: undefined,
    jank: undefined,
    long: {
      block: undefined,
      count: undefined,
      max: undefined,
    },
    nav: {
      dur: undefined,
      pending: false,
    },
  })

  const target = createMemo(
    () => {
      const session = sessions.current()

      if (!session?.id) return

      return { server: session.server, data: session.server.data, id: session.id }
    },
    undefined,
    { equals: (a, b) => a?.data === b?.data && a?.id === b?.id },
  )

  // The numbers on the TUI's latest assistant footer, which follows a step that ended the turn, failed, or is retrying.
  const turn = createMemo(() => {
    const current = target()

    if (!current) return

    const messages = current.data.session.message.list(current.id)

    const index = messages.findLastIndex(
      (item) =>
        item.type === "assistant" &&
        Boolean(item.retry || item.error || (item.finish && !["tool-calls", "unknown"].includes(item.finish))),
    )

    if (index === -1) return

    const options = { index, legacy: SessionTurn.legacy(messages) }
    // The TUI hides a zero duration, which means the step has not completed.
    const elapsed = SessionTurn.duration(messages, messages[index], options)

    return {
      duration: elapsed ? duration(elapsed) : undefined,
      tps: SessionTurn.tokensPerSecond(messages, messages[index], options),
    }
  })

  // The Motion workspace's global speed, kept in view while tuning.
  const [globals, setGlobals] = createSignal({ speed: motionGlobals.speed.value, slow: motionGlobals.slow.value })
  onCleanup(
    motionTuning.subscribe(() => setGlobals({ speed: motionGlobals.speed.value, slow: motionGlobals.slow.value })),
  )

  const na = () => ctx.t("na").toUpperCase()
  const heap = () => (state.heap.limit ? (state.heap.used ?? 0) / state.heap.limit : undefined)

  const heapv = () => {
    const value = heap()

    if (value === undefined) return na()

    return `${Math.round(value * 100)}%`
  }

  const longv = () => (state.long.count === undefined ? na() : `${time(state.long.block) ?? na()}/${state.long.count}`)
  const navv = () => (state.nav.pending ? "…" : (time(state.nav.dur) ?? na()))

  const toggleFocus = async () => {
    if (!desktop) return
    const enabled = !state.focus
    await desktop.forceFocus(enabled)
    setState("focus", enabled)
  }

  onCleanup(() => {
    if (state.focus) void desktop?.forceFocus(false).catch(() => undefined)
  })

  let prev = ""
  let start = 0
  let init = false
  let one = 0
  let two = 0

  // Times navigations to and from a session: from the route starting to change until two frames after it settles.
  createKeyed(
    () => props.diagnostics && { busy: router.routing(), next: router.path() },
    (route) => {
      const next = route.next

      if (!init) {
        init = true
        prev = next

        return
      }

      if (route.busy) {
        if (one !== 0) cancelAnimationFrame(one)

        if (two !== 0) cancelAnimationFrame(two)
        one = 0
        two = 0

        if (start !== 0) return
        start = performance.now()

        if (session(prev)) setState("nav", { dur: undefined, pending: true })

        return
      }

      if (start === 0) {
        prev = next

        return
      }

      const at = start
      const from = prev

      start = 0
      prev = next

      if (!(session(from) || session(next))) return

      if (one !== 0) cancelAnimationFrame(one)

      if (two !== 0) cancelAnimationFrame(two)
      one = requestAnimationFrame(() => {
        one = 0
        two = requestAnimationFrame(() => {
          two = 0
          setState("nav", { dur: performance.now() - at, pending: false })
        })
      })
    },
  )

  onMount(() => {
    if (!props.diagnostics) return
    const obs: PerformanceObserver[] = []
    const fps: Array<{ at: number; dur: number }> = []
    const long: Array<{ at: number; dur: number }> = []
    const seen = new Map<number | string, { at: number; delay: number; dur: number }>()
    let hasLong = false
    let poll: number | undefined
    let raf = 0
    let last = 0
    let snap = 0

    const trim = (list: Array<{ at: number; dur: number }>, span: number, at: number) => {
      while (list[0] && at - list[0].at > span) list.shift()
    }

    const syncFrame = (at: number) => {
      trim(fps, span, at)
      const total = fps.reduce((sum, entry) => sum + entry.dur, 0)
      const gap = fps.reduce((max, entry) => Math.max(max, entry.dur), 0)
      const jank = fps.filter((entry) => entry.dur > 32).length
      batch(() => {
        setState("fps", total > 0 ? (fps.length * 1000) / total : undefined)
        setState("gap", gap > 0 ? gap : undefined)
        setState("jank", jank)
      })
    }

    const syncLong = (at = performance.now()) => {
      if (!hasLong) return
      trim(long, span, at)
      const block = long.reduce((sum, entry) => sum + Math.max(0, entry.dur - 50), 0)
      const max = long.reduce((hi, entry) => Math.max(hi, entry.dur), 0)
      setState("long", { block, count: long.length, max })
    }

    const syncInp = (at = performance.now()) => {
      for (const [key, entry] of seen) {
        if (at - entry.at > span) seen.delete(key)
      }

      let delay = 0
      let inp = 0

      for (const entry of seen.values()) {
        delay = Math.max(delay, entry.delay)
        inp = Math.max(inp, entry.dur)
      }

      batch(() => {
        setState("delay", delay > 0 ? delay : undefined)
        setState("inp", inp > 0 ? inp : undefined)
      })
    }

    const syncHeap = () => {
      const timing: Mem = performance
      const mem = timing.memory

      if (!mem) return
      setState("heap", { limit: mem.jsHeapSizeLimit, used: mem.usedJSHeapSize })
    }

    const reset = () => {
      fps.length = 0
      long.length = 0
      seen.clear()
      last = 0
      snap = 0
      batch(() => {
        setState("fps", undefined)
        setState("gap", undefined)
        setState("jank", undefined)
        setState("delay", undefined)
        setState("inp", undefined)

        if (hasLong) setState("long", { block: 0, count: 0, max: 0 })
      })
    }

    const watch = (type: string, init: Obs, fn: (entries: PerformanceEntry[]) => void) => {
      if (typeof PerformanceObserver === "undefined") return false

      if (!(PerformanceObserver.supportedEntryTypes ?? []).includes(type)) return false
      const ob = new PerformanceObserver((list) => fn(list.getEntries()))

      try {
        ob.observe(init)
        obs.push(ob)

        return true
      } catch {
        ob.disconnect()

        return false
      }
    }

    if (
      watch("layout-shift", { buffered: true, type: "layout-shift" }, (entries) => {
        const add = entries.reduce((sum, entry) => {
          // SAFETY: this observer subscribes to "layout-shift" entries alone, which carry these fields.
          const item = entry as Shift

          if (item.hadRecentInput) return sum

          return sum + item.value
        }, 0)

        if (add === 0) return
        setState("cls", (value) => (value ?? 0) + add)
      })
    ) {
      setState("cls", 0)
    }

    if (
      watch("longtask", { buffered: true, type: "longtask" }, (entries) => {
        const at = performance.now()
        long.push(...entries.map((entry) => ({ at: entry.startTime, dur: entry.duration })))
        syncLong(at)
      })
    ) {
      hasLong = true
      setState("long", { block: 0, count: 0, max: 0 })
    }

    watch("event", { buffered: true, durationThreshold: 16, type: "event" }, (entries) => {
      for (const raw of entries) {
        // SAFETY: this observer subscribes to "event" entries alone, which carry these optional fields.
        const entry = raw as Evt

        if (entry.duration < 16) continue

        const key =
          entry.interactionId && entry.interactionId > 0
            ? entry.interactionId
            : `${entry.name}:${Math.round(entry.startTime)}`

        const prev = seen.get(key)
        const delay = Math.max(0, (entry.processingStart ?? entry.startTime) - entry.startTime)
        seen.set(key, {
          at: entry.startTime,
          delay: Math.max(prev?.delay ?? 0, delay),
          dur: Math.max(prev?.dur ?? 0, entry.duration),
        })

        if (seen.size <= 200) continue
        const first = seen.keys().next().value

        if (first !== undefined) seen.delete(first)
      }

      syncInp()
    })

    const loop = (at: number) => {
      if (document.visibilityState !== "visible") {
        raf = 0

        return
      }

      if (last === 0) {
        last = at
        raf = requestAnimationFrame(loop)

        return
      }

      fps.push({ at, dur: at - last })
      last = at

      if (at - snap >= 250) {
        snap = at
        syncFrame(at)
      }

      raf = requestAnimationFrame(loop)
    }

    const stop = () => {
      if (raf !== 0) cancelAnimationFrame(raf)
      raf = 0

      if (poll === undefined) return
      clearInterval(poll)
      poll = undefined
    }

    const start = () => {
      if (document.visibilityState !== "visible") return

      if (poll === undefined) {
        poll = window.setInterval(() => {
          syncLong()
          syncInp()
          syncHeap()
        }, 1000)
      }

      if (raf !== 0) return
      raf = requestAnimationFrame(loop)
    }

    const vis = () => {
      if (document.visibilityState !== "visible") {
        stop()

        return
      }

      reset()
      start()
    }

    syncHeap()
    start()
    makeEventListener(document, "visibilitychange", vis)

    onCleanup(() => {
      if (one !== 0) cancelAnimationFrame(one)

      if (two !== 0) cancelAnimationFrame(two)
      stop()

      for (const ob of obs) ob.disconnect()
    })
  })

  return (
    <aside
      aria-label={ctx.t(props.diagnostics ? "ariaLabel" : "providerAriaLabel")}
      classList={{
        "pointer-events-auto hidden overflow-hidden text-text-strong md:block": true,
        "mt-[-6px] w-full shrink-0 px-3 py-1": !!props.inline,
        "fixed bottom-3 right-3 z-50 w-[308px] max-w-[calc(100vw-1.5rem)] rounded-xl border border-v2-border-border-base bg-surface-raised-stronger-non-alpha p-0.5 shadow-[var(--shadow-lg-border-base)] sm:bottom-4 sm:right-4 sm:w-[324px]":
          !props.inline,
      }}
    >
      <div
        classList={{
          "font-mono": true,
          "gap-[9px]": !!props.inline,
          "gap-px": !props.inline,
          "flex w-full flex-nowrap items-center justify-start": !!props.inline,
          "grid-cols-4": !props.inline,
          grid: !props.inline,
        }}
      >
        <Show when={props.onClose}>
          <Tooltip appearance="compact" value={ctx.t("close.tip")} placement="top">
            <IconButton
              size="small"
              variant="ghost-muted"
              icon={<Icon name="close" />}
              aria-label={ctx.t("close.label")}
              onClick={() => props.onClose?.()}
            />
          </Tooltip>
        </Show>
        <Cell
          label={ctx.t("duration.label")}
          tip={ctx.t("duration.tip")}
          value={turn()?.duration ?? na()}
          dim={turn()?.duration === undefined}
          inline={props.inline}
        />
        <Cell
          label={ctx.t("tps.label")}
          tip={ctx.t("tps.tip")}
          value={fixed(turn()?.tps, 1) ?? na()}
          dim={turn()?.tps === undefined}
          inline={props.inline}
        />
        <Show when={props.diagnostics}>
          <Cell
            label={ctx.t("nav.label")}
            tip={ctx.t("nav.tip")}
            value={navv()}
            bad={bad(state.nav.dur, 400)}
            dim={state.nav.dur === undefined && !state.nav.pending}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("fps.label")}
            tip={ctx.t("fps.tip")}
            value={state.fps === undefined ? na() : `${Math.round(state.fps)}`}
            bad={bad(state.fps, 50, true)}
            dim={state.fps === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("frame.label")}
            tip={ctx.t("frame.tip")}
            value={time(state.gap) ?? na()}
            bad={bad(state.gap, 50)}
            dim={state.gap === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("jank.label")}
            tip={ctx.t("jank.tip")}
            value={state.jank === undefined ? na() : `${state.jank}`}
            bad={bad(state.jank, 8)}
            dim={state.jank === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("long.label")}
            tip={ctx.t("long.tip", { max: ms(state.long.max) ?? na() })}
            value={longv()}
            bad={bad(state.long.block, 200)}
            dim={state.long.count === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("delay.label")}
            tip={ctx.t("delay.tip")}
            value={time(state.delay) ?? na()}
            bad={bad(state.delay, 100)}
            dim={state.delay === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("inp.label")}
            tip={ctx.t("inp.tip")}
            value={time(state.inp) ?? na()}
            bad={bad(state.inp, 200)}
            dim={state.inp === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("cls.label")}
            tip={ctx.t("cls.tip")}
            value={state.cls === undefined ? na() : state.cls.toFixed(2)}
            bad={bad(state.cls, 0.1)}
            dim={state.cls === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("mem.label")}
            tip={
              state.heap.used === undefined
                ? ctx.t("mem.tipUnavailable")
                : ctx.t("mem.tip", {
                    used: mb(state.heap.used) ?? na(),
                    limit: mb(state.heap.limit) ?? na(),
                  })
            }
            value={heapv()}
            bad={bad(heap(), 0.8)}
            dim={state.heap.used === undefined}
            inline={props.inline}
            span={desktop ? 2 : 3}
          />
          <ToggleCell
            active={locale.direction() === "rtl"}
            inline={props.inline}
            label={ctx.t("direction.label")}
            tip={ctx.t("direction.tip")}
            value={ctx.t(`direction.${locale.direction()}`)}
            onClick={() => locale.setDirection(locale.direction() === "rtl" ? "ltr" : "rtl")}
          />
          <Show when={desktop}>
            <ToggleCell
              active={state.focus}
              inline={props.inline}
              label={ctx.t("focus.label")}
              tip={ctx.t("focus.tip")}
              value={ctx.t(state.focus ? "focus.on" : "focus.off")}
              onClick={() => void toggleFocus()}
            />
          </Show>
        </Show>
        <Show when={props.memory}>
          {(memory) => (
            <ToggleCell
              active={memory().on}
              inline={props.inline}
              label={ctx.t("memory.label")}
              tip={ctx.t(memory().env ? "memory.tipEnv" : "memory.tip")}
              value={ctx.t(memory().env ? "memory.env" : memory().on ? "focus.on" : "focus.off")}
              onClick={() => memory().toggle()}
            />
          )}
        </Show>
        <Show when={props.motion}>
          <div class="ms-auto flex items-center gap-[9px]">
            {/* The lab's route exists only on the dev server and in Beta. */}
            {(import.meta.env.DEV || import.meta.env.VITE_OPENCODE_CHANNEL === "beta") && (
              <Tooltip appearance="compact" value={ctx.t("components.tip")} placement="top">
                <a
                  href="/components"
                  classList={{
                    "flex min-h-[20px] w-fit items-center rounded px-1.5 py-0.5 font-mono uppercase hover:bg-surface-raised-base focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-v2-border-border-focus": true,
                    "bg-surface-raised-base text-text-strong": router.path().startsWith("/components"),
                  }}
                >
                  <span
                    dir="ltr"
                    class="-translate-y-px text-[10px] leading-none font-black tracking-[0.04em] opacity-70"
                  >
                    {ctx.t("components.label")}
                  </span>
                </a>
              </Tooltip>
            )}
            <ToggleCell
              active={globals().speed !== 1}
              inline={props.inline}
              label={ctx.t("speed.label")}
              tip={ctx.t("speed.tip")}
              value={`${globals().speed.toFixed(2)}×`}
              onClick={() => motionTuning.set(motionGlobals.speed, nextSpeed(globals().speed))}
            />
            <ToggleCell
              active={globals().slow}
              inline={props.inline}
              label={ctx.t("slow.label")}
              tip={ctx.t("slow.tip")}
              value={ctx.t(globals().slow ? "focus.on" : "focus.off")}
              onClick={() => motionTuning.set(motionGlobals.slow, !globals().slow)}
            />
            <ToggleCell
              active={!!props.motion?.open}
              inline={props.inline}
              label={ctx.t("motion.label")}
              tip={ctx.t("motion.tip")}
              value={ctx.t(props.motion?.open ? "focus.on" : "focus.off")}
              onClick={() => props.motion?.toggle()}
            />
          </div>
        </Show>
      </div>
    </aside>
  )
}

// The bar's speed cell steps through the common slow-downs, then back to full speed.
function nextSpeed(speed: number) {
  return [0.5, 0.25, 1].find((step) => step < speed) ?? 1
}
